1	// Official entry point for evidence runs of the SignalScout pipelines.
2	//
3	//   npx tsx scripts/run-pipeline.ts --pipeline baseline
4	//   npx tsx scripts/run-pipeline.ts --pipeline improved --llm real --confirm-spend
5	//   npx tsx scripts/run-pipeline.ts --pipeline improved --provider crustdata --confirm-spend
6	//
7	// Options: --pipeline baseline|improved, --llm fake|real (default fake),
8	// --provider fixture|crustdata (default fixture), --confirm-spend (required
9	// with --llm real or --provider crustdata), --label <string> (default:
10	// pipeline name), --config dev|eval (default eval), --trace on|off (fixture
11	// only; crustdata runs are never traced), and for crustdata runs --industry
12	// (default "Staffing and Recruiting"), --country (default "India") and
13	// --sizes (default "11-50,51-200"). CRUSTDATA_API_KEY must be set for crustdata.
14	//
15	// Writes runs/<timestamp>-<label>.json with counts, ids, costs, issue codes,
16	// tokens and timings only: no company records, keys or headers.
17	
18	import { mkdir, writeFile } from "node:fs/promises";
19	import {
20	  FakeLlmClient,
21	  type LlmClient,
22	  type LlmRequest,
23	  type LlmResponse,
24	  type PipelineResult,
25	  PROMPT_SAFETY_RULES,
26	  PROMPT_VERSION,
27	  type PipelineTracer,
28	  computeBaselineCitationMetrics,
29	  describeIcp,
30	  noopTracer,
31	  runBaselinePipeline,
32	  runImprovedPipeline,
33	} from "../src/core/agent";
34	import { createGatewayLlmClient } from "../src/core/agent/gateway-client";
35	import { CrustdataProvider } from "../src/core/data/crustdata-provider";
36	import { FixtureProvider } from "../src/core/data/fixture-provider";
37	import { BudgetGuard, type CompanyProvider } from "../src/core/data/provider";
38	import { validateCompanies } from "../src/core/data/validation";
39	import {
40	  DEFAULT_RUN_CONFIG,
41	  DEV_RUN_CONFIG,
42	  type RawCompany,
43	  type RunConfig,
44	} from "../src/core/types";
45	import {
46	  type PostHocValidation,
47	  type ResolvedRun,
48	  buildRunIcp,
49	  exitCodeForError,
50	  exitCodeForStatus,
51	  formatOutreachLine,
52	  parseRunArgs,
53	  recordSystemHashes,
54	  sha256Hex,
55	  summarizeGuardFindings,
56	  summarizeOutreachKept,
57	  summarizeValidation,
58	  UsageError,
59	  validateRunArgs,
60	} from "./run-metrics";
61	
62	// What the evidence ICP means in words; matches describeIcp for the open ICP.
63	const EVIDENCE_ICP_DESCRIPTION = "Companies in any industry of any size in any location.";
64	
65	// Simulated at measured Crustdata prices (USD per record).
66	const SIMULATED_COST_PER_RECORD = { search: 0.069, enrich: 0.6 } as const;
67	
68	const EVAL_RUN_CONFIG: RunConfig = {
69	  ...DEFAULT_RUN_CONFIG,
70	  max_search_results: 10,
71	  max_enrichments: 5,
72	};
73	
74	// Both pipelines see the same records: Crustdata's default order is not stable
75	// between calls, so crustdata runs sort by company id.
76	const CRUSTDATA_SEARCH_SORT = { field: "crustdata_company_id", order: "asc" } as const;
77	
78	type Args = ResolvedRun;
79	
80	function buildLlm(kind: Args["llm"]): LlmClient {
81	  if (kind === "fake") return new FakeLlmClient();
82	  const apiKey = process.env.LITELLM_API_KEY;
83	  if (apiKey === undefined || apiKey.trim() === "") {
84	    throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
85	  }
86	  return createGatewayLlmClient({ apiKey });
87	}
88	
89	// Fake-client token counts are made up; only real gateway usage is measured.
90	function tokenBasis(kind: Args["llm"]): "simulated" | "measured" {
91	  return kind === "fake" ? "simulated" : "measured";
92	}
93	
94	function fileSafe(label: string): string {
95	  return label.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "run";
96	}
97	
98	// Delegates to the real or fake client and records only the hashes of the
99	// system messages it is asked to send, never their text.
100	class HashingLlmClient implements LlmClient {
101	  readonly system_hashes = new Set<string>();
102	
103	  constructor(private readonly inner: LlmClient) {}
104	
105	  get records_llm_spans(): boolean {
106	    return this.inner.records_llm_spans;
107	  }
108	
109	  complete(request: LlmRequest): Promise<LlmResponse> {
110	    recordSystemHashes(request.messages, this.system_hashes);
111	    return this.inner.complete(request);
112	  }
113	}
114	
115	function postHocValidation(searched: readonly RawCompany[], result: PipelineResult): PostHocValidation {
116	  // The pipeline returns one prospect per searched company, in search order.
117	  return summarizeValidation(
118	    validateCompanies(searched),
119	    result.prospects.map((p) => ({
120	      company_id: p.raw.crustdata_company_id,
121	      enriched: p.enrichment.status === "enriched",
122	      delivered: p.assessment.status === "assessed",
123	    })),
124	  );
125	}
126	
127	interface ProviderSpend {
128	  search: number;
129	  enrich: number;
130	}
131	
132	function buildReport(
133	  args: Args,
134	  config: RunConfig,
135	  icp_description: string,
136	  result: PipelineResult,
137	  started_at: string,
138	  prompt: { readonly system_prompt_hashes: readonly string[] },
139	  validation: PostHocValidation,
140	  spend: ProviderSpend,
141	) {
142	  const { run, usage } = result;
143	  const fact_provider = args.provider;
144	  const simulated = args.provider === "fixture";
145	  return {
146	    started_at,
147	    label: args.label,
148	    pipeline: args.pipeline,
149	    provider: args.provider,
150	    fact_provider,
151	    tracing: args.tracing ? "on" : "off",
152	    search_sort: simulated ? null : CRUSTDATA_SEARCH_SORT,
153	    icp_description,
154	    // ICP parameters from the flags; no company data.
155	    icp_flags: simulated ? null : { industry: args.industry, country: args.country, sizes: args.sizes },
156	    config_name: args.config,
157	    config,
158	    trace_id: run.trace_id,
159	    status: result.status,
160	    counts: run.counts,
161	    cost_usd_by_step: run.cost_usd_by_step,
162	    timings_ms_by_step: run.timings_ms_by_step,
163	    cost_basis: {
164	      provider: simulated ? "simulated" : "measured",
165	      ...(simulated && { provider_cost_per_record_usd: SIMULATED_COST_PER_RECORD }),
166	      provider_cost_usd: { search: spend.search, enrich: spend.enrich, total: spend.search + spend.enrich },
167	      llm_calls_by_basis: usage.llm_cost.calls_by_basis,
168	    },
169	    provider_usage: usage.provider,
170	    llm: {
171	      mode: args.llm,
172	      token_basis: tokenBasis(args.llm),
173	      calls: usage.llm_calls,
174	      http_attempts: usage.llm_http_attempts,
175	      input_tokens: run.counts.llm_input_tokens,
176	      output_tokens: run.counts.llm_output_tokens,
177	      gateway_reported_usd: usage.llm_cost.gateway_reported_usd,
178	      estimated_usd: usage.llm_cost.estimated_usd,
179	      known_usd: usage.llm_cost.known_usd,
180	      cost_complete: usage.llm_cost.complete,
181	    },
182	    prompt_provenance: {
183	      prompt_version: PROMPT_VERSION,
184	      prompt_safety_rules_sha256: sha256Hex(PROMPT_SAFETY_RULES),
185	      system_prompt_hashes: prompt.system_prompt_hashes,
186	    },
187	    post_hoc_validation: validation,
188	    // Both pipelines: the final outreach drafts, measured after the fact with
189	    // the same function (for improved, the drafts that survived the guards).
190	    outreach_kept: summarizeOutreachKept(result.prospects),
191	    citation_metrics: computeBaselineCitationMetrics(result, fact_provider),
192	    // Improved only: its own guardrail counts (null when it stopped before
193	    // validation) and findings by code. Counts and ids only.
194	    improved_metrics: args.pipeline === "improved" ? (result.metrics ?? null) : null,
195	    guard_findings: args.pipeline === "improved" ? summarizeGuardFindings(result.prospects, result.metrics) : null,
196	    issue_codes: result.issues.map((i) => i.code),
197	    company_ids: result.prospects.map((p) => p.raw.crustdata_company_id),
198	    prospects: result.prospects.map((p) => ({
199	      company_id: p.raw.crustdata_company_id,
200	      enrichment: p.enrichment.status,
201	      assessment: p.assessment.status,
202	      llm_call_number: p.llm_call?.call_number ?? null,
203	    })),
204	  };
205	}
206	
207	function buildProvider(args: Args, config: RunConfig): CompanyProvider & { readonly budget: BudgetGuard } {
208	  if (args.provider === "fixture") {
209	    return new FixtureProvider({ config, cost_per_record: SIMULATED_COST_PER_RECORD });
210	  }
211	  // Presence was checked by validateRunArgs before anything was built.
212	  return new CrustdataProvider({
213	    api_key: process.env.CRUSTDATA_API_KEY ?? "",
214	    budget: new BudgetGuard(config),
215	    search_sort: CRUSTDATA_SEARCH_SORT,
216	  });
217	}
218	
219	// Tracing is loaded lazily so a crustdata or --trace off run never imports or
220	// initialises neatlogs.
221	async function withTracing<T>(
222	  args: Args,
223	  fn: (tracer: PipelineTracer) => Promise<T>,
224	): Promise<T> {
225	  if (!args.tracing) return fn(noopTracer);
226	  const { span } = await import("neatlogs");
227	  const { neatlogsTracer } = await import("../src/core/agent/neatlogs-tracer");
228	  const { closeTracing, initTracing } = await import("../src/core/observability/tracing");
229	  await initTracing({ run_label: args.label });
230	  try {
231	    return await span({ kind: "WORKFLOW", name: "signalscout_run" }, () => fn(neatlogsTracer))();
232	  } finally {
233	    await closeTracing();
234	  }
235	}
236	
237	async function main(): Promise<void> {
238	  const args = validateRunArgs(parseRunArgs(process.argv.slice(2)), process.env);
239	  const config = args.config === "dev" ? DEV_RUN_CONFIG : EVAL_RUN_CONFIG;
240	  const icp = buildRunIcp(args);
241	  const icp_description =
242	    args.provider === "fixture" ? EVIDENCE_ICP_DESCRIPTION : describeIcp(icp);
243	
244	  const provider = buildProvider(args, config);
245	  const llm = new HashingLlmClient(buildLlm(args.llm));
246	  const searched: RawCompany[] = [];
247	  const spend: ProviderSpend = { search: 0, enrich: 0 };
248	  const recordingProvider: CompanyProvider = {
249	    autocompleteIndustry: (query) => provider.autocompleteIndustry(query),
250	    async enrichCompanies(urls) {
251	      const res = await provider.enrichCompanies(urls);
252	      if (res.ok) spend.enrich += res.cost_usd;
253	      return res;
254	    },
255	    async searchCompanies(filters, limit) {
256	      const res = await provider.searchCompanies(filters, limit);
257	      if (res.ok) {
258	        searched.push(...res.data);
259	        spend.search += res.cost_usd;
260	      }
261	      return res;
262	    },
263	  };
264	  const started_at = new Date().toISOString();
265	
266	  const result = await withTracing(args, (tracer) => {
267	    const deps = { provider: recordingProvider, budget: provider.budget, llm, tracer };
268	    return args.pipeline === "baseline"
269	      ? runBaselinePipeline(icp, deps, { config })
270	      : runImprovedPipeline(icp, { ...deps, fact_provider: args.provider }, { config });
271	  });
272	
273	  const system_prompt_hashes = [...llm.system_hashes].sort();
274	  const validation = postHocValidation(searched, result);
275	  const report = buildReport(args, config, icp_description, result, started_at, { system_prompt_hashes }, validation, spend);
276	  await mkdir("runs", { recursive: true });
277	  const path = `runs/${started_at.replace(/[:.]/g, "-")}-${fileSafe(args.label)}.json`;
278	  await writeFile(path, `${JSON.stringify(report, null, 2)}\n`);
279	
280	  const { counts, cost_usd_by_step: cost } = result.run;
281	  const llmCost = result.usage.llm_cost;
282	  const costBasis = args.provider === "fixture" ? "simulated at measured Crustdata prices" : "measured";
283	  console.log(`run ${result.run.trace_id}  status=${result.status}  label=${args.label}`);
284	  console.log(
285	    `setup    pipeline=${args.pipeline} provider=${args.provider} fact_provider=${args.provider} tracing=${args.tracing ? "on" : "off"}` +
286	      ` search_sort=${args.provider === "fixture" ? "none" : `${CRUSTDATA_SEARCH_SORT.field} ${CRUSTDATA_SEARCH_SORT.order}`}`,
287	  );
288	  console.log(
289	    `counts   searched=${counts.searched} enriched=${counts.enriched} delivered=${counts.delivered} llm_calls=${counts.llm_calls}`,
290	  );
291	  console.log(`tokens   in=${counts.llm_input_tokens} out=${counts.llm_output_tokens}  (${tokenBasis(args.llm)})`);
292	  console.log(
293	    `provider search=$${cost.search.toFixed(3)} enrich=$${cost.enrich.toFixed(3)}  (${costBasis}; provider-returned total=$${(spend.search + spend.enrich).toFixed(3)})`,
294	  );
295	  console.log(
296	    `llm      gateway_reported=$${llmCost.gateway_reported_usd.toFixed(4)} (${llmCost.calls_by_basis.gateway_reported} calls)` +
297	      `  estimated=$${llmCost.estimated_usd.toFixed(4)} (${llmCost.calls_by_basis.estimated} calls)` +
298	      `  unavailable=${llmCost.calls_by_basis.unavailable} calls`,
299	  );
300	  console.log(
301	    `prompt   version=${PROMPT_VERSION} safety_rules_sha256=${sha256Hex(PROMPT_SAFETY_RULES).slice(0, 12)} system_hashes=${system_prompt_hashes.join(",") || "none"}`,
302	  );
303	  const fmt = (c: { valid: number; flagged: number; rejected: number }) =>
304	    `valid=${c.valid} flagged=${c.flagged} rejected=${c.rejected}`;
305	  console.log("post-hoc validation (counts)");
306	  console.log(`  searched  ${fmt(validation.searched)}`);
307	  console.log(`  enriched  ${fmt(validation.enriched)}  wasted_enrichments=${validation.wasted_enrichments}`);
308	  console.log(`  delivered ${fmt(validation.delivered)}  duplicate_groups=${validation.delivered_duplicate_groups}`);
309	  const m = computeBaselineCitationMetrics(result, args.provider);
310	  if (args.pipeline === "baseline") {
311	    console.log(
312	      `citations assessed=${m.assessed} drafts=${m.outreach_drafts} cited=${m.cited_fact_ids} citeable=${m.citeable} missing=${m.missing}` +
313	        ` cross_company=${m.cross_company} model_provider=${m.model_provider} uncertain=${m.uncertain}` +
314	        ` other_non_citeable=${m.other_non_citeable} drafts_with_violations=${m.drafts_with_violations.count}`,
315	    );
316	  } else if (result.metrics) {
317	    const im = result.metrics;
318	    console.log(
319	      `improved rejected=${im.rejected.count} flagged=${im.flagged.count} duplicates_removed=${im.duplicates_removed.count}` +
320	        ` eligible=${im.enrichment.eligible.count} requested=${im.enrichment.requested.count} enriched=${im.enrichment.enriched.count}` +
321	        ` assessments_failed=${im.assessments_failed.count} outreach_suppressed=${im.outreach_suppressed.count}` +
322	        ` claim_violations=${im.claim_violations.count} (drafts=${im.claim_violations.drafts})`,
323	    );
324	    const g = summarizeGuardFindings(result.prospects, im);
325	    const byCode = (r: Readonly<Record<string, number>>) =>
326	      Object.entries(r)
327	        .map(([code, n]) => `${code}=${n}`)
328	        .join(",") || "none";
329	    console.log(`guards   findings: ${byCode(g.findings_by_code)}  claim_violations: ${byCode(g.claim_violations_by_code)}`);
330	  } else {
331	    console.log("improved metrics unavailable (the run stopped before validation)");
332	  }
333	  console.log(formatOutreachLine(summarizeOutreachKept(result.prospects), m));
334	  console.log(`issues   ${result.issues.map((i) => i.code).join(", ") || "none"}`);
335	  console.log(`report   ${path}`);
336	  if (result.status === "stopped") {
337	    console.error("The run stopped early; see the issue codes above.");
338	  }
339	  process.exitCode = exitCodeForStatus(result.status);
340	}
341	
342	main().catch((err) => {
343	  console.error(
344	    err instanceof UsageError ? err.message : `Run failed: ${err instanceof Error ? err.message : "unknown error"}`,
345	  );
346	  process.exitCode = exitCodeForError(err);
347	});
