83	// Key used to group duplicates: domain first, LinkedIn URL when no domain.
84	function duplicateKey(raw: RawCompany): string | undefined {
85	  const domain = normalizeDomain(raw.primary_domain);
86	  if (domain) return `domain:${domain}`;
87	  const linkedin = normalizeLinkedInUrl(raw.professional_network_url);
88	  if (linkedin) return `linkedin:${linkedin}`;
89	  return undefined;
90	}
91	
92	function sizeIssues(raw: RawCompany): ValidationIssue[] {
93	  const issues: ValidationIssue[] = [];
94	  const headcount = raw.latest_headcount;
95	  if (
96	    typeof headcount !== "number" ||
97	    !Number.isFinite(headcount) ||
98	    headcount <= 0
99	  ) {
100	    return issues;
101	  }
102	
103	  const range = parseEmployeeRange(raw.employee_count_range);
104	  if (range && (headcount < range.min || headcount > range.max)) {
105	    issues.push({
106	      code: "size_headcount_mismatch",
107	      field: "latest_headcount",
108	      reason: `Headcount ${headcount} is outside the listed size range "${raw.employee_count_range}".`,
109	    });
110	  }
111	
112	  const revenueMin = parseRevenueLowerBound(raw.revenue_range);
113	  if (
114	    revenueMin !== undefined &&
115	    revenueMin / headcount > MAX_REVENUE_PER_EMPLOYEE_USD
116	  ) {
117	    issues.push({
118	      code: "size_headcount_mismatch",
119	      field: "revenue_range",
120	      reason: `Revenue "${raw.revenue_range}" with ${headcount} employees implies more than $${MAX_REVENUE_PER_EMPLOYEE_USD.toLocaleString("en-US")} per employee, which is implausible.`,
121	    });
122	  }
123	  return issues;
124	}
